package com.codearena.controller;
import com.codearena.entity.*;import com.codearena.repository.*;import com.codearena.service.Judge0ExecutionService;import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
import java.util.*;
@RestController public class ExecuteController {
 @Autowired Judge0ExecutionService judge;@Autowired ProblemRepository problems;@Autowired SubmissionRepository submissions;@Autowired UserRepository users;ObjectMapper mapper=new ObjectMapper();
 private Map<String,Object> parse(String s){try{return mapper.readValue(s,Map.class);}catch(Exception e){return null;}}
 @PostMapping("/api/execute") public ResponseEntity<?> execute(@RequestBody Map<String,Object>b){try{String code=(String)b.get("code"),language=(String)b.get("language"),problemId=(String)b.get("problemId");Integer id=judge.languageId(language);if(id==null)return ResponseEntity.badRequest().body(Map.of("error","Unsupported language"));Object runTests=b.get("runTests");boolean submit=Boolean.TRUE.equals(runTests)&&problemId!=null;if(!submit){Object custom=b.get("customCases");List<Map<String,Object>>cases=new ArrayList<>();Optional<Problem>p=problemId==null?Optional.empty():problems.findById(problemId);if(p.isPresent())for(Object x:judge.parseJsonArray(p.get().getExamples()))if(x instanceof Map)cases.add((Map)x);if(custom instanceof List)for(Object x:(List<?>)custom)if(x instanceof Map){Map<String,Object>c=new LinkedHashMap<>((Map)x);c.put("custom",true);cases.add(c);}if(cases.isEmpty()){Map<String,Object>r=judge.submit(code,id);return plain(r);}List<Map<String,Object>>results=new ArrayList<>();int passed=0;double total=0;long max=0;int totalCases=0;for(int i=0;i<cases.size();i++){Map<String,Object>c=cases.get(i);boolean customCase=Boolean.TRUE.equals(c.get("custom"));String input=Objects.toString(c.get("input"),"");String expected=Objects.toString(c.get("output"),"");try{Map<String,Object>r=judge.submit(judge.buildRunnableCode(code,language,input,expected),id);String stdout=Objects.toString(r.get("stdout"),"");String stderr=Objects.toString(r.get("stderr")!=null?r.get("stderr"):r.get("compile_output"),"");double time=parseDouble(r.get("time"));long memory=num(r.get("memory"));boolean ok=!customCase&&Judge0ExecutionService.normalizeOutput(stdout).equals(Judge0ExecutionService.normalizeOutput(expected))&&statusId(r)==3;if(ok)passed++;total+=time*1000;max=Math.max(max,memory);Map<String,Object>x=new LinkedHashMap<>();x.put("testCase",i+1);x.put("input",input);x.put("expected",expected);x.put("output",stdout.isBlank()?stderr.trim():stdout.trim());x.put("passed",ok);x.put("time",time*1000);x.put("memory",memory);x.put("error",stderr);x.put("status",statusDesc(r));x.put("custom",customCase);results.add(x);if(!customCase)totalCases++;}catch(Exception e){Map<String,Object>error=new LinkedHashMap<>();error.put("testCase",i+1);error.put("input",input);error.put("expected",expected);error.put("output","");error.put("passed",false);error.put("time",0);error.put("memory",0);error.put("error",e.getMessage());error.put("status","Error");error.put("custom",customCase);results.add(error);if(!customCase)totalCases++;}}return ResponseEntity.ok(Map.of("results",results,"passed",passed,"total",totalCases,"accepted",false,"totalTime",total,"maxMemory",max));}
 Optional<Problem>p=problems.findById(problemId);if(p.isEmpty())return ResponseEntity.status(404).body(Map.of("error","Problem not found"));List<Map<String,Object>>tests=new ArrayList<>();for(Object x:judge.parseJsonArray(p.get().getTestCases()))if(x instanceof Map)tests.add((Map)x);if(tests.isEmpty())for(Object x:judge.parseJsonArray(p.get().getExamples()))if(x instanceof Map)tests.add((Map)x);if(tests.isEmpty())return ResponseEntity.badRequest().body(Map.of("error","No test cases for this problem"));List<Map<String,Object>>results=new ArrayList<>();int passed=0;double total=0;long max=0;for(int i=0;i<tests.size();i++){Map<String,Object>tc=tests.get(i);String input=Objects.toString(tc.get("input"),"");String expected=Objects.toString(tc.containsKey("expectedOutput")?tc.get("expectedOutput"):tc.get("output"),"");try{Map<String,Object>r=judge.submit(judge.buildRunnableCode(code,language,input,expected),id);String stdout=Objects.toString(r.get("stdout"),"");String stderr=Objects.toString(r.get("stderr")!=null?r.get("stderr"):r.get("compile_output"),"");boolean ok=Judge0ExecutionService.normalizeOutput(stdout).equals(Judge0ExecutionService.normalizeOutput(expected))&&statusId(r)==3;double time=parseDouble(r.get("time"));long memory=num(r.get("memory"));if(ok)passed++;total+=time*1000;max=Math.max(max,memory);Map<String,Object>x=new LinkedHashMap<>();x.put("testCase",i+1);x.put("input",input);x.put("expected",expected);x.put("output",stdout.trim().isBlank()?stderr.trim():stdout.trim());x.put("passed",ok);x.put("time",time*1000);x.put("memory",memory);x.put("error",stderr);x.put("status",statusDesc(r));x.put("timeLimitExceeded",statusId(r)==5);x.put("memoryLimitExceeded",statusId(r)==6);results.add(x);}catch(Exception e){Map<String,Object>error=new LinkedHashMap<>();error.put("testCase",i+1);error.put("input",input);error.put("expected",expected);error.put("output","");error.put("passed",false);error.put("time",0);error.put("memory",0);error.put("error",e.getMessage());error.put("status","Error");error.put("timeLimitExceeded",false);error.put("memoryLimitExceeded",false);results.add(error);}}boolean accepted=passed==tests.size();String verdict=accepted?"Accepted":"Wrong Answer ("+passed+"/"+tests.size()+")";Map<String,Object>out=new LinkedHashMap<>();out.put("results",results);out.put("passed",passed);out.put("total",tests.size());out.put("accepted",accepted);out.put("totalTime",total);out.put("maxMemory",max);out.put("verdict",verdict);Object userId=b.get("userId");if(userId!=null&&users.findById(userId.toString()).isPresent()){Submission s=new Submission();s.setUserId(userId.toString());s.setProblemId(problemId);s.setCode(code);s.setLanguage(language);s.setStatus(accepted?"Accepted":"Wrong Answer");s.setVerdict(verdict);s.setRuntime((int)Math.round(total));s.setMemory((int)Math.round(max));s.setPassed(passed);s.setTotal(tests.size());try{submissions.save(s);}catch(Exception ignored){}}return ResponseEntity.ok(out);}catch(Exception e){return ResponseEntity.status(500).body(Map.of("error","Execution failed","details",e.getMessage()));}}
 private ResponseEntity<Map<String,Object>>plain(Map<String,Object>r){String stderr=Objects.toString(r.get("stderr")!=null?r.get("stderr"):r.get("compile_output"),"");String stdout=Objects.toString(r.get("stdout"),"");Map<String,Object>x=new LinkedHashMap<>();x.put("testCase",1);x.put("input","");x.put("expected","");x.put("output",stdout.isBlank()?stderr.isBlank()?"No output":stderr:stdout);x.put("passed",false);x.put("time",parseDouble(r.get("time"))*1000);x.put("memory",num(r.get("memory")));x.put("error",stderr);x.put("status",statusDesc(r));x.put("custom",true);return ResponseEntity.ok(Map.of("results",List.of(x),"passed",0,"total",1,"accepted",false,"totalTime",0,"maxMemory",num(r.get("memory"))));}
 private int statusId(Map<String,Object>r){Object s=r.get("status");return s instanceof Map&&((Map<?,?>)s).get("id")instanceof Number?((Number)((Map<?,?>)s).get("id")).intValue():0;}private String statusDesc(Map<String,Object>r){Object s=r.get("status");return s instanceof Map&&((Map<?,?>)s).get("description")!=null?((Map<?,?>)s).get("description").toString():"Unknown";}private double parseDouble(Object o){try{return Double.parseDouble(Objects.toString(o,"0"));}catch(Exception e){return 0;}}private long num(Object o){return o instanceof Number?((Number)o).longValue():0L;}
}
